member.example:
 An action with two properties:

 using Kjs.AppLife.Update.Engine.Core;

 public class MyAction : UpdateAction {
	  private int mNumber;
	  private string mText;

	  public MyAction() { }

	  public int Number {
	    get { return mNumber; }
	    set { mNumber = value; }
	  }

	  public string Text {
	    get { return mText; }
	    set { mText = value; }
	  }

	  public override void Execute(UpdateContext context) {
	    return;
	  }

	  public override void RollbackExecute(UpdateContext context) {
	    return;
	  }
 }


 Imports Kjs.AppLife.Update.Engine.Core

 Public Class MyAction
   Inherits UpdateAction

   Dim mNumber As Integer
   Dim mText As String

   Public Sub New()
   End Sub

   Public Property Number() As Integer
     Get
       Return mNumber
     End Get
     Set(ByVal value As Integer)
       mNumber = value
     End Set
   End Property

   Public Property Text() As String
     Get
       Return mText
     End Get
     Set(ByVal value As String)
       mText = value
     End Set
   End Property

   Public Overrides Sub Execute(ByVal context As UpdateContext)
   End Sub

   Public Overrides Sub RollbackExecute(ByVal context As UpdateContext)
   End Sub
 End Class

 An action with a customized display name:

 using Kjs.AppLife.Update.Engine.Core;

 [System.ComponentModel.DisplayName("My other action")]
 public class MyOtherAction : UpdateAction {
	  public MyOtherAction() { }

	  public override void Execute(UpdateContext context) {
	    return;
	  }

	  public override void RollbackExecute(UpdateContext context) {
	    return;
	  }
 }


 Imports Kjs.AppLife.Update.Engine.Core

 <System.ComponentModel.DisplayName("My other action")> _
 Public Class MyOtherAction
   Inherits UpdateAction

   Public Sub New()
   End Sub

   Public Overrides Sub Execute(ByVal context As UpdateContext)
   End Sub

   Public Overrides Sub RollbackExecute(ByVal context As UpdateContext)
   End Sub
 End Class
